<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {request,demoMode} from '@/services/quality'
import AppModal from '@/components/AppModal.vue'
interface Account {id:number;name:string;email:string;is_active:boolean;account_version:number;is_platform_admin:boolean}
const rows=ref<Account[]>([]);const selected=ref<Account|null>(null);const search=ref('');const page=ref(1);const last=ref(1);const reason=ref('');const busy=ref(false);const open=ref(false);const error=ref('');const notice=ref('')
async function load(){error.value='';try{const d=await request<{data:Account[];last_page:number}>('/platform/accounts?'+new URLSearchParams({search:search.value,page:String(page.value)}));rows.value=d.data;last.value=d.last_page}catch(e){error.value=(e as Error).message}}
function edit(a:Account){selected.value=a;reason.value='';error.value='';open.value=true}
async function save(){busy.value=true;error.value='';try{await request('/platform/accounts/'+selected.value!.id+'/state','POST',{version:selected.value!.account_version,is_active:!selected.value!.is_active,reason:reason.value});open.value=false;notice.value='État enregistré. Les sessions et liens de sécurité précédents ont été révoqués.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{if(!demoMode)load()})
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 01 · ADMINISTRATION PLATEFORME</p><h1>État des comptes</h1><p class="page-subtitle">La désactivation globale coupe toutes les appartenances, sans supprimer les données.</p></div></div><p v-if="demoMode" class="panel form-body">Administration disponible dans l’aperçu API.</p><template v-else><p v-if="error&&!open" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><div class="panel"><form class="table-toolbar" @submit.prevent="page=1;load()"><label class="search-field"><input v-model="search" maxlength="120" placeholder="Nom ou email" aria-label="Rechercher un compte"/></label><button class="button secondary">Rechercher</button></form><div class="table-scroll"><table><thead><tr><th>COMPTE</th><th>ÉTAT GLOBAL</th><th>VERSION</th><th>ACTION</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td>{{a.name}}<span class="table-subtitle">{{a.email}}{{a.is_platform_admin?' · Administration plateforme':''}}</span></td><td>{{a.is_active?'Actif':'Désactivé'}}</td><td>{{a.account_version}}</td><td><button class="button secondary small" @click="edit(a)">{{a.is_active?'Désactiver':'Réactiver'}}</button></td></tr></tbody></table></div><div class="panel-heading"><button class="button secondary" :disabled="page<=1" @click="page--;load()">Précédent</button><span>{{page}} / {{last}}</span><button class="button secondary" :disabled="page>=last" @click="page++;load()">Suivant</button></div></div></template><AppModal v-model="open" title="Confirmer l’état global du compte" :busy="busy"><form id="account-state" class="form-body correction-form" @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{error}}</p><p>{{selected?.name}} · {{selected?.email}}</p><p>Les sessions existantes seront révoquées. Vous ne pouvez pas modifier votre propre état, ni laisser une officine sans administrateur actif.</p><label>Motif obligatoire<textarea v-model="reason" required rows="4" maxlength="2000"/></label></form><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Annuler</button><button class="button primary" :disabled="busy" form="account-state" type="submit">Confirmer</button></template></AppModal></section></template>
